test "AsmJit x86_64 assembler tests (400..800)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    const x = @import("x86_64/assembler.zig");
    const gp = @import("x86_64/gp.zig");
    var fails: u32 = 0;
    fails += check(&.{ 0xF7, 0xBC, 0x11, 0x80, 0x00, 0x00, 0x00 }, .@"idiv", .{ gp.r32(.rdx), gp.r32(.rax), gp.dword(x.ptrIdx(.rcx, .rdx, .x1, 128)) }, "idiv(edx, eax, dword_ptr(rcx, rdx, 0, 128))");
    fails += check(&.{ 0x48, 0xF7, 0xF9 }, .@"idiv", .{ gp.r64(.rdx), gp.r64(.rax), gp.r64(.rcx) }, "idiv(rdx, rax, rcx)");
