    fails += check(&.{ 0x48, 0xF7, 0xBC, 0x11, 0x80, 0x00, 0x00, 0x00 }, .@"idiv", .{ gp.r64(.rdx), gp.r64(.rax), gp.qword(x.ptrIdx(.rcx, .rdx, .x1, 128)) }, "idiv(rdx, rax, qword_ptr(rcx, rdx, 0, 128))");
