test "AsmJit x86_64 assembler tests (1200..1266)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    const x = @import("x86_64/assembler.zig");
    const gp = @import("x86_64/gp.zig");
    var fails: u32 = 0;
    fails += check(&.{ 0x0F, 0x01, 0xD6 }, .@"xtest", .{  }, "xtest()");
    fails += check(&.{ 0x01, 0xCB }, .@"add", .{ gp.r32(.rbx), gp.r32(.rcx) }, "add(ebx, ecx)");
    fails += check(&.{ 0x83, 0xC0, 0x01 }, .@"add", .{ gp.r32(.rax), 1 }, "add(eax, 1)");
    fails += check(&.{ 0x05, 0x04, 0x03, 0x02, 0x01 }, .@"add", .{ gp.r32(.rax), 16909060 }, "add(eax, 0x01020304)");
    fails += check(&.{ 0x66, 0x05, 0x02, 0x01 }, .@"add", .{ gp.r16(.rax), 258 }, "add(ax, 0x0102)");
    fails += check(&.{ 0x66, 0x03, 0x84, 0x90, 0x04, 0x03, 0x02, 0x01 }, .@"add", .{ gp.r16(.rax), gp.mem(x.ptrIdx(.rax, .rdx, .x4, 16909060)) }, "add(ax, ptr(rax, rdx, 2, 0x01020304))");
    fails += check(&.{ 0x48, 0x8D, 0x04, 0x33 }, .@"lea", .{ gp.r64(.rax), gp.mem(x.ptrIdx(.rbx, .rsi, .x1, 0)) }, "lea(rax, ptr(rbx, rsi))");
    fails += check(&.{ 0x48, 0x8D, 0x04, 0x3B }, .@"lea", .{ gp.r64(.rax), gp.mem(x.ptrIdx(.rbx, .rdi, .x1, 0)) }, "lea(rax, ptr(rbx, rdi))");
    fails += check(&.{ 0x48, 0x8D, 0x84, 0x00, 0x00, 0x40, 0x00, 0x00 }, .@"lea", .{ gp.r64(.rax), gp.mem(x.ptrIdx(.rax, .rax, .x1, 16384)) }, "lea(rax, ptr(rax, rax, 0, 0x4000))");
    fails += check(&.{ 0x48, 0xBB, 0x88, 0x77, 0x66, 0x55, 0x44, 0x33, 0x22, 0x11 }, .@"mov", .{ gp.r64(.rbx), 1234605616436508552 }, "mov(rbx, 0x001122334455667788)");
    fails += check(&.{ 0xB8, 0xE8, 0x03, 0x00, 0x00 }, .@"mov", .{ gp.r32(.rax), 1000 }, "mov(eax, 1000)");
    fails += check(&.{ 0x4A, 0x8B, 0x04, 0x60 }, .@"mov", .{ gp.r64(.rax), gp.mem(x.ptrIdx(.rax, .r12, .x2, 0)) }, "mov(rax, ptr(rax, r12, 1))");
    fails += check(&.{ 0x4A, 0x8B, 0x04, 0x68 }, .@"mov", .{ gp.r64(.rax), gp.mem(x.ptrIdx(.rax, .r13, .x2, 0)) }, "mov(rax, ptr(rax, r13, 1))");
    fails += check(&.{ 0x4A, 0x8B, 0x84, 0x60, 0x00, 0x01, 0x00, 0x00 }, .@"mov", .{ gp.r64(.rax), gp.mem(x.ptrIdx(.rax, .r12, .x2, 256)) }, "mov(rax, ptr(rax, r12, 1, 256))");
    fails += check(&.{ 0x0F, 0xBE, 0x07 }, .@"movsx", .{ gp.r32(.rax), gp.byte(x.ptr(.rdi, 0)) }, "movsx(eax, byte_ptr(rdi))");
    fails += check(&.{ 0x48, 0x0F, 0xBE, 0x07 }, .@"movsx", .{ gp.r64(.rax), gp.byte(x.ptr(.rdi, 0)) }, "movsx(rax, byte_ptr(rdi))");
    fails += check(&.{ 0x0F, 0xBF, 0x07 }, .@"movsx", .{ gp.r32(.rax), gp.word(x.ptr(.rdi, 0)) }, "movsx(eax, word_ptr(rdi))");
    fails += check(&.{ 0x48, 0x0F, 0xBF, 0x07 }, .@"movsx", .{ gp.r64(.rax), gp.word(x.ptr(.rdi, 0)) }, "movsx(rax, word_ptr(rdi))");
    fails += check(&.{ 0x48, 0x63, 0x07 }, .@"movsxd", .{ gp.r64(.rax), gp.mem(x.ptr(.rdi, 0)) }, "movsxd(rax, ptr(rdi))");
    fails += check(&.{ 0x48, 0x63, 0x07 }, .@"movsxd", .{ gp.r64(.rax), gp.dword(x.ptr(.rdi, 0)) }, "movsxd(rax, dword_ptr(rdi))");
    fails += check(&.{ 0x66, 0x63, 0xC3 }, .@"movsxd", .{ gp.r16(.rax), gp.r16(.rbx) }, "movsxd(ax, bx)");
