    fails += check(&.{ 0x44, 0x0F, 0xB6, 0xFA }, .@"movzx", .{ gp.r32(.r15), gp.r8(.rdx) }, "movzx(r15d, dl)");
    fails += check(&.{ 0x44, 0x0F, 0xB6, 0xFD }, .@"movzx", .{ gp.r32(.r15), gp.r8(.rbp) }, "movzx(r15d, bpl)");
