    fails += check(&.{ 0xF6, 0xD8 }, .@"neg", .{ gp.r8(.rax) }, "neg(al)");
    fails += check(&.{ 0xF6, 0xDC }, .@"neg", .{ gp.r8hi(.rax) }, "neg(ah)");
    fails += check(&.{ 0x40, 0xF6, 0xDE }, .@"neg", .{ gp.r8(.rsi) }, "neg(sil)");
    fails += check(&.{ 0xF7, 0xD8 }, .@"neg", .{ gp.r32(.rax) }, "neg(eax)");
    fails += check(&.{ 0xF7, 0xD0 }, .@"not", .{ gp.r32(.rax) }, "not_(eax)");
    fails += check(&.{ 0x0F, 0x95, 0xC3 }, .@"setnz", .{ gp.r8(.rbx) }, "setnz(bl)");
    fails += check(&.{ 0x0F, 0x94, 0xC7 }, .@"setz", .{ gp.r8hi(.rbx) }, "setz(bh)");
    fails += check(&.{ 0x41, 0x0F, 0x94, 0xC7 }, .@"setz", .{ gp.r8(.r15) }, "setz(r15b)");
    fails += check(&.{ 0xF6, 0x00, 0xFF }, .@"test", .{ gp.byte(x.ptr(.rax, 0)), 255 }, "test(byte_ptr(rax), 0xFF)");
    fails += check(&.{ 0x66, 0xF7, 0x00, 0xFF, 0x00 }, .@"test", .{ gp.word(x.ptr(.rax, 0)), 255 }, "test(word_ptr(rax), 0xFF)");
    fails += check(&.{ 0xF7, 0x00, 0xFF, 0x00, 0x00, 0x00 }, .@"test", .{ gp.dword(x.ptr(.rax, 0)), 255 }, "test(dword_ptr(rax), 0xFF)");
    fails += check(&.{ 0x48, 0xF7, 0x00, 0xFF, 0x00, 0x00, 0x00 }, .@"test", .{ gp.qword(x.ptr(.rax, 0)), 255 }, "test(qword_ptr(rax), 0xFF)");
    fails += check(&.{ 0xA8, 0x36 }, .@"test", .{ gp.r8(.rax), 54 }, "test(al, 0x36)");
    fails += check(&.{ 0xF6, 0xC4, 0x36 }, .@"test", .{ gp.r8hi(.rax), 54 }, "test(ah, 0x36)");
    fails += check(&.{ 0x50 }, .@"push", .{ gp.r64(.rax) }, "push(rax)");
    fails += check(&.{ 0x51 }, .@"push", .{ gp.r64(.rcx) }, "push(rcx)");
    fails += check(&.{ 0x52 }, .@"push", .{ gp.r64(.rdx) }, "push(rdx)");
    fails += check(&.{ 0x53 }, .@"push", .{ gp.r64(.rbx) }, "push(rbx)");
    fails += check(&.{ 0x54 }, .@"push", .{ gp.r64(.rsp) }, "push(rsp)");
    fails += check(&.{ 0x55 }, .@"push", .{ gp.r64(.rbp) }, "push(rbp)");
    fails += check(&.{ 0x56 }, .@"push", .{ gp.r64(.rsi) }, "push(rsi)");
    fails += check(&.{ 0x57 }, .@"push", .{ gp.r64(.rdi) }, "push(rdi)");
    fails += check(&.{ 0x41, 0x50 }, .@"push", .{ gp.r64(.r8) }, "push(r8)");
    fails += check(&.{ 0x41, 0x51 }, .@"push", .{ gp.r64(.r9) }, "push(r9)");
    fails += check(&.{ 0x41, 0x52 }, .@"push", .{ gp.r64(.r10) }, "push(r10)");
    fails += check(&.{ 0x41, 0x53 }, .@"push", .{ gp.r64(.r11) }, "push(r11)");
    fails += check(&.{ 0x41, 0x54 }, .@"push", .{ gp.r64(.r12) }, "push(r12)");
    fails += check(&.{ 0x41, 0x55 }, .@"push", .{ gp.r64(.r13) }, "push(r13)");
    fails += check(&.{ 0x41, 0x56 }, .@"push", .{ gp.r64(.r14) }, "push(r14)");
    fails += check(&.{ 0x41, 0x57 }, .@"push", .{ gp.r64(.r15) }, "push(r15)");
    fails += check(&.{ 0x66, 0x90 }, .@"xchg", .{ gp.r16(.rax), gp.r16(.rax) }, "xchg(ax, ax)");
